function validate([prices]) {
  if (!Array.isArray(prices) || prices.length < 1 || prices.length > 100000) return 'prices needs 1 to 100000 values.';
  if (prices.some(p => !Number.isInteger(p) || p < 0 || p > 100000)) return 'Each price is an integer between 0 and 100000.';
  return null;
}

