function maxProfit(prices) {
  const n = prices.length;
  let best = 0;
  for (let i = 0; i < n; i++)
    for (let j = i + 1; j < n; j++) {
      const first = prices[j] - prices[i];
      best = Math.max(best, first);
      for (let k = j + 1; k < n; k++)
        for (let l = k + 1; l < n; l++)
          best = Math.max(best, first + prices[l] - prices[k]);
    }
  return best;
}

