function generate(rand, size) {
  if (size === 'large') {
    const prices = Array.from({ length: 2000 }, () => Math.floor(rand() * 100001));
    return [prices];
  }
  const n = 1 + Math.floor(rand() * 9);
  const top = rand() < 0.6 ? 10 : 100000;
  return [Array.from({ length: n }, () => Math.floor(rand() * (top + 1)))];
}
